-- Create "account_tokens" table
CREATE TABLE "account_tokens" ("id" uuid NOT NULL, "token_hash" bytea NOT NULL, "purpose" character varying NOT NULL, "email_canonical" character varying NOT NULL, "user_id" uuid NULL, "issued_auth_version" bigint NULL, "app_id" character varying NOT NULL, "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "account_tokens_app_id" CHECK ((char_length((app_id)::text) >= 1) AND (char_length((app_id)::text) <= 64)), CONSTRAINT "account_tokens_auth_floor" CHECK ((issued_auth_version IS NULL) OR (issued_auth_version >= 1)), CONSTRAINT "account_tokens_binding" CHECK ((((purpose)::text = 'registration'::text) AND (user_id IS NULL) AND (issued_auth_version IS NULL)) OR (((purpose)::text = 'password_reset'::text) AND (user_id IS NOT NULL) AND (issued_auth_version IS NOT NULL))), CONSTRAINT "account_tokens_email" CHECK (((email_canonical)::text = lower((email_canonical)::text)) AND (octet_length((email_canonical)::text) <= 254)), CONSTRAINT "account_tokens_expiry" CHECK (expires_at > created_at), CONSTRAINT "account_tokens_hash_size" CHECK (octet_length(token_hash) = 32), CONSTRAINT "account_tokens_purpose" CHECK ((purpose)::text = ANY ((ARRAY['registration'::character varying, 'password_reset'::character varying])::text[])));
-- Create index "account_tokens_token_hash_key" to table: "account_tokens"
CREATE UNIQUE INDEX "account_tokens_token_hash_key" ON "account_tokens" ("token_hash");
-- Create index "accounttoken_email_canonical_purpose" to table: "account_tokens"
CREATE INDEX "accounttoken_email_canonical_purpose" ON "account_tokens" ("email_canonical", "purpose");
-- Create index "accounttoken_expires_at" to table: "account_tokens"
CREATE INDEX "accounttoken_expires_at" ON "account_tokens" ("expires_at");
-- Create index "accounttoken_user_id" to table: "account_tokens"
CREATE INDEX "accounttoken_user_id" ON "account_tokens" ("user_id");
-- Create "deletion_tombstones" table
CREATE TABLE "deletion_tombstones" ("user_id" uuid NOT NULL, "mutation_id" character varying NOT NULL, "completed_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, PRIMARY KEY ("user_id"), CONSTRAINT "deletion_tombstones_expiry" CHECK (expires_at > completed_at), CONSTRAINT "deletion_tombstones_mutation" CHECK ((char_length((mutation_id)::text) >= 1) AND (char_length((mutation_id)::text) <= 64)));
-- Create index "deletiontombstone_expires_at" to table: "deletion_tombstones"
CREATE INDEX "deletiontombstone_expires_at" ON "deletion_tombstones" ("expires_at");
-- Create "security_audit" table
CREATE TABLE "security_audit" ("id" uuid NOT NULL, "user_id" uuid NULL, "actor" character varying NOT NULL DEFAULT '', "action" character varying NOT NULL, "request_id" character varying NOT NULL DEFAULT '', "result" character varying NOT NULL, "reason" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "security_audit_action" CHECK ((char_length((action)::text) >= 1) AND (char_length((action)::text) <= 64)), CONSTRAINT "security_audit_actor" CHECK (char_length((actor)::text) <= 64), CONSTRAINT "security_audit_reason" CHECK (char_length((reason)::text) <= 200), CONSTRAINT "security_audit_result" CHECK ((char_length((result)::text) >= 1) AND (char_length((result)::text) <= 64)));
-- Create index "securityaudit_created_at" to table: "security_audit"
CREATE INDEX "securityaudit_created_at" ON "security_audit" ("created_at");
-- Create index "securityaudit_user_id_created_at" to table: "security_audit"
CREATE INDEX "securityaudit_user_id_created_at" ON "security_audit" ("user_id", "created_at");
-- Create "users" table
CREATE TABLE "users" ("id" uuid NOT NULL, "email_canonical" character varying NOT NULL, "email_verified_at" timestamptz NOT NULL, "password_hash" character varying NOT NULL, "display_name" character varying NOT NULL DEFAULT '旅行者', "avatar_url" character varying NOT NULL DEFAULT '', "profile_version" bigint NOT NULL DEFAULT 1, "status" character varying NOT NULL DEFAULT 'active', "auth_version" bigint NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "deletion_started_at" timestamptz NULL, "deletion_mutation_id" character varying NULL, PRIMARY KEY ("id"), CONSTRAINT "users_auth_version" CHECK (auth_version >= 1), CONSTRAINT "users_avatar_url" CHECK (octet_length((avatar_url)::text) <= 500), CONSTRAINT "users_deletion_marker" CHECK (((status)::text = 'deleting'::text) = ((deletion_mutation_id IS NOT NULL) AND (deletion_started_at IS NOT NULL))), CONSTRAINT "users_deletion_mutation" CHECK ((deletion_mutation_id IS NULL) OR ((char_length((deletion_mutation_id)::text) >= 1) AND (char_length((deletion_mutation_id)::text) <= 64))), CONSTRAINT "users_display_name" CHECK ((char_length((display_name)::text) >= 1) AND (char_length((display_name)::text) <= 40)), CONSTRAINT "users_email_canonical" CHECK (((email_canonical)::text = lower((email_canonical)::text)) AND (octet_length((email_canonical)::text) <= 254)), CONSTRAINT "users_password_hash_size" CHECK ((char_length((password_hash)::text) >= 1) AND (char_length((password_hash)::text) <= 512)), CONSTRAINT "users_profile_version" CHECK (profile_version >= 1), CONSTRAINT "users_status" CHECK ((status)::text = ANY ((ARRAY['active'::character varying, 'disabled'::character varying, 'deleting'::character varying])::text[])));
-- Create index "users_email_canonical_key" to table: "users"
CREATE UNIQUE INDEX "users_email_canonical_key" ON "users" ("email_canonical");
-- Create "user_roles" table
CREATE TABLE "user_roles" ("id" uuid NOT NULL, "role" character varying NOT NULL, "granted_at" timestamptz NOT NULL, "granted_by" character varying NOT NULL DEFAULT '', "user_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "user_roles_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "user_roles_role" CHECK ((role)::text = 'metro-admin'::text));
-- Create index "userrole_user_id_role" to table: "user_roles"
CREATE UNIQUE INDEX "userrole_user_id_role" ON "user_roles" ("user_id", "role");
